    if (st.locked) return { ok: false, msg: `${weapon.name} \u5C1A\u672A\u4E0A\u67B6\uFF1A${st.reason}\u3002` };
    if (!st.afford) return { ok: false, msg: `\u661F\u5E01\u4E0D\u8DB3\uFF0C${st.reason}\u3002` };
    gameData.credits -= weapon.cost;
    if (!Array.isArray(gameData.ownedWeapons)) gameData.ownedWeapons = [];
