        if (dishIdx === -1) {
          return { success: false, msg: `\u5C1A\u672A\u70F9\u996A\u597D\u76EE\u6807\u6599\u7406\uFF1A${bounty.targetName}\uFF01` };
        }
        this.gameState.cookedDishes.splice(dishIdx, 1);
