    chop: { name: "\u5241\u788E", hint: "\u5728\u98DF\u6750\u4E0A\u8FDE\u7EED\u6572\u51FB\uFF0C\u4FDD\u6301\u7A33\u5B9A\u8282\u594F" },
    grind: { name: "\u7814\u78E8", hint: "\u5728\u98DF\u6750\u4E0A\u753B\u5708\u7814\u78E8\uFF0C\u78E8\u5230\u8D28\u5730\u7EC6\u817B" }
